// Flatten every run's transcript down to visitor turns only. The agent's own
// replies are noise for FAQ clustering — we want what people ASKED.
const questions = [];

for (const item of $input.all()) {
  const transcript = item.json.transcript;
  if (!Array.isArray(transcript)) continue;
  for (const turn of transcript) {
    if (turn?.role !== 'user') continue;
    const text = String(turn.content ?? '').trim();
    if (text.length < 8 || text.length > 400) continue;
    questions.push(text);
  }
}

if (questions.length === 0) {
  return [];  // nothing to cluster; downstream nodes are skipped
}

return [{ json: { count: questions.length, corpus: questions.join('\n---\n') } }];

