={{ JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 4096,
  output_config: {
    effort: 'low',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          faqs: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                question: { type: 'string' },
                frequency: { type: 'integer' }
              },
              required: ['question', 'frequency'],
              additionalProperties: false
            }
          }
        },
        required: ['faqs'],
        additionalProperties: false
      }
    }
  },
  messages: [{
    role: 'user',
    content: 'Below are visitor questions from an IT services company website chat, one per block, separated by ---. Cluster them into at most 15 distinct recurring questions. For each cluster write the question in the clearest neutral phrasing a visitor would recognise, and set frequency to how many raw questions fall into that cluster. Drop one-off questions that appear only once. Do not invent questions that are not represented in the input.\n\n' + $json.corpus
  }]
}) }}

