// Structured outputs guarantee the first text block is valid JSON matching the
// schema — so a plain parse is safe here, no defensive retry needed.
const res = $input.first().json;

if (res.stop_reason === 'refusal') {
  throw new Error('Clustering call was refused: ' + JSON.stringify(res.stop_details ?? {}));
}

const textBlock = (res.content ?? []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('No text block in the model response.');

const { faqs } = JSON.parse(textBlock.text);

return faqs.map((f) => ({ json: { question: f.question, frequency: f.frequency } }));
